import { Component, input, OnInit, signal } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import Quill, { Delta, QuillOptions } from 'quill';

const quillOptions: QuillOptions = {
  theme: 'snow',
  modules: {
    toolbar: [
      ['bold', 'italic', 'underline', 'strike'],
      [{ header: [1, 2, 3, 4, false] }],
      [{ list: 'ordered' }, { list: 'bullet' }],
    ],
  },
};

function convertDeltaToString(delta: Delta) {
  return JSON.stringify({ delta });
}

function convertStringToDelta(string: string) {
  return JSON.parse(string);
}

@Component({
  selector: 'app-rich-text',
  imports: [],
  templateUrl: './rich-text.component.html',
  styleUrl: './rich-text.component.scss',
})
export class RichTextComponent implements OnInit {
  parentForm = input.required<FormGroup>();
  quill = signal<Quill | null>(null);
  controller = new AbortController();
  summary = new FormControl('', {
    validators: [Validators.required],
  });

  ngOnInit() {
    this.quill.set(new Quill('#editor', quillOptions));
    this.parentForm()?.addControl('summary', this.summary);
    this.quill()?.on(
      'text-change',
      () => {
        // Get data in html format:  console.log('html', this.quill()?.container.innerHTML);
        const currentDelta = this.quill()?.getContents();
        if (currentDelta) {
          this.summary.setValue(convertDeltaToString(currentDelta));
          console.log('summary', this.summary.value);
        } else {
          this.summary.setValue('');
        }
      },
      { signal: this.controller.signal }
    );
  }

  ngOnDestroy() {
    this.controller.abort();
  }
}

import { Component, inject, input, OnInit, signal } from '@angular/core';
import { ButtonModule } from 'primeng/button';
import {
  FormArray,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
} from '@angular/forms';
import { InputTextModule } from 'primeng/inputtext';
import { IftaLabelModule } from 'primeng/iftalabel';
import { SelectModule } from 'primeng/select';
import {
  Social,
  SOCIAL_OPTIONS_PROVIDER,
  SOCIAL_OPTIONS_TOKEN,
  SocialItem,
} from '../../../types/social';
import { DialogModule } from 'primeng/dialog';

@Component({
  selector: 'app-social',
  imports: [
    ButtonModule,
    ReactiveFormsModule,
    InputTextModule,
    IftaLabelModule,
    SelectModule,
    DialogModule,
  ],
  templateUrl: './social.component.html',
  styleUrl: './social.component.scss',
  providers: [SOCIAL_OPTIONS_PROVIDER],
})
export class SocialComponent implements OnInit {
  parentForm = input<FormGroup>();
  socialOptions = inject(SOCIAL_OPTIONS_TOKEN);
  isDialogOpen = signal(false);

  socialForm = new FormGroup({
    social: new FormArray<FormControl<SocialItem>>([]),
  });

  ngOnInit(): void {
    this.parentForm()?.addControl('socialForm', this.socialForm);
  }

  addSocial(url: string, type: Social) {
    if (!url || !type) {
      return;
    }
    this.socialForm.controls.social.push(
      new FormControl<SocialItem>(
        {
          url,
          type,
        },
        { nonNullable: true }
      )
    );
    this.closeDialog();
  }

  openDialog() {
    this.isDialogOpen.set(true);
  }

  closeDialog() {
    console.log('closeDialog');
    this.isDialogOpen.set(false);
  }

  removeSocial(index: number) {
    this.socialForm.controls.social.removeAt(index);
  }
}

